begin;
create table if not exists public.mme_bi_metric_definitions(metric_id uuid primary key default gen_random_uuid(),metric_key text not null unique,display_name text not null,description text,source_system text not null,aggregation text not null check(aggregation in ('sum','count','average','ratio','latest')),unit text not null default 'number',is_active boolean not null default true,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_bi_metric_snapshots(snapshot_id uuid primary key default gen_random_uuid(),metric_id uuid not null references public.mme_bi_metric_definitions(metric_id),period_start timestamptz not null,period_end timestamptz not null,dimension_key text not null default 'all',dimension_value text not null default 'all',metric_value numeric(18,4) not null,source_reference text,source_updated_at timestamptz,created_at timestamptz not null default now(),check(period_end>=period_start),unique(metric_id,period_start,period_end,dimension_key,dimension_value));
create table if not exists public.mme_bi_report_definitions(report_id uuid primary key default gen_random_uuid(),report_key text not null unique,report_name text not null,description text,configuration jsonb not null default '{}',cadence text not null default 'manual' check(cadence in ('manual','daily','weekly','monthly')),is_active boolean not null default true,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_bi_alert_rules(alert_rule_id uuid primary key default gen_random_uuid(),rule_key text not null unique,rule_name text not null,metric_key text not null,operator text not null check(operator in ('gt','gte','lt','lte','eq','neq')),threshold numeric(18,4) not null,severity text not null default 'warning' check(severity in ('info','warning','critical')),is_active boolean not null default true,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_bi_alert_events(alert_event_id uuid primary key default gen_random_uuid(),alert_rule_id uuid references public.mme_bi_alert_rules(alert_rule_id),metric_key text not null,observed_value numeric(18,4),threshold numeric(18,4),severity text not null check(severity in ('info','warning','critical')),status text not null default 'open' check(status in ('open','acknowledged','resolved')),message text not null,source_reference text,created_at timestamptz not null default now(),acknowledged_by_auth_user_id uuid,acknowledged_at timestamptz,resolved_by_auth_user_id uuid,resolved_at timestamptz);
create table if not exists public.mme_bi_ingestion_runs(ingestion_id uuid primary key default gen_random_uuid(),source_system text not null,started_at timestamptz not null default now(),finished_at timestamptz,status text not null default 'running' check(status in ('running','succeeded','partial','failed')),records_read integer not null default 0 check(records_read>=0),records_written integer not null default 0 check(records_written>=0),error_summary text,request_id uuid not null,created_by_auth_user_id uuid not null);
create index if not exists mme_bi_snapshot_metric_period_idx on public.mme_bi_metric_snapshots(metric_id,period_start desc);
create index if not exists mme_bi_alert_status_idx on public.mme_bi_alert_events(status,severity,created_at desc);
create index if not exists mme_bi_ingestion_source_idx on public.mme_bi_ingestion_runs(source_system,started_at desc);
alter table public.mme_bi_metric_definitions enable row level security;alter table public.mme_bi_metric_snapshots enable row level security;alter table public.mme_bi_report_definitions enable row level security;alter table public.mme_bi_alert_rules enable row level security;alter table public.mme_bi_alert_events enable row level security;alter table public.mme_bi_ingestion_runs enable row level security;
do $$ declare t text; begin foreach t in array array['mme_bi_metric_definitions','mme_bi_metric_snapshots','mme_bi_report_definitions','mme_bi_alert_rules','mme_bi_alert_events','mme_bi_ingestion_runs'] loop execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
commit;